sys_ux_data_broker_transform.script:
function transform(input) {
    var kpiProperties = [
        'sam.foundation.current.company.kpi',
        'sam.foundation.current.users.kpi',
        'sam.foundation.current.costcenter.kpi',
        'sam.foundation.current.businessunit.kpi',
        'sam.foundation.current.department.kpi',
        'sam.foundation.current.location.kpi'
    ];

    var results = {}; // Change to an object to store arrays by property name

    for (var p = 0; p < kpiProperties.length; p++) {
        var kpiPropertyName = kpiProperties[p];
        var kpiProperty = gs.getProperty(kpiPropertyName);
        var entityType = kpiPropertyName.split('.')[3];
        var tableName = '';
        var fieldName = '';
        var kpiLabel = '';
        var indicatorSysid = '';

        try {
            if (kpiProperty) {
                var kpiConfigs = JSON.parse(kpiProperty);
                for (var i = 0; i < kpiConfigs.length; i++) {
                    var config = kpiConfigs[i];
                    if (config.kpi && config.kpi.toLowerCase().indexOf('duplicate') > -1) {
                        tableName = config.table;
                        fieldName = config.field;
                        kpiLabel = config.kpi || ('Duplicate ' + entityType.charAt(0).toUpperCase() + entityType.slice(1));
                        indicatorSysid = config.indicatorSysid || 'fb007202d7130100b96d45a3ce6103b4';
                        break;
                    }
                }
            }
        } catch (e) {
            gs.error('Error parsing KPI property ' + kpiPropertyName + ': ' + e);
            continue;
        }

        if (!tableName || !fieldName) {
            continue;
        }

        var totalDuplicateCount = 0;
        var gr = new GlideAggregate(tableName);
        gr.addAggregate('COUNT', fieldName);
        gr.groupBy(fieldName);
        gr.addNotNullQuery(fieldName);
        gr.addHaving('COUNT', '>', 1);
        gr.query();

        while (gr.next()) {
            var count = parseInt(gr.getAggregate('COUNT', fieldName), 10);
            totalDuplicateCount += (count - 1);
        }

        // Create the result object for this property
        var resultObject = {
            "data": [
                {
                    "value": totalDuplicateCount,
                    "change": "0",
                    "changePercent": "0"
                }
            ],
            "metadata": {
                "eventData": {
                    "indicatorSysid": indicatorSysid
                },
                "previousScoreDate": "1642809600000",
                "dataSourceLabel": "Number of duplicate " + entityType + "s",
                "changeArrow": "steady",
                "scoreDate": "1642896000000",
                "filterQuery": fieldName + "ISNOTEMPTY",
                "aggregate": {
                    "fieldType": "decimal"
                },
                "format": {
                    "unitFormat": "{0}",
                    "frequency": "daily",
                    "precision": 0
                },
                "entityType": entityType
            },
            "sparkline": {
                "data": [
                    {
                        "timestamp": "1637798400000",
                        "value": totalDuplicateCount
                    }
                ],
                "metadata": {
                    "eventData": {
                        "indicatorSysid": indicatorSysid
                    },
                    "dataSourceLabel": "Number of duplicate " + entityType + "s",
                    "series": [
                        {
                            "label": "Duplicate " + entityType.charAt(0).toUpperCase() + entityType.slice(1) + "s",
                            "id": "value",
                            "type": "value"
                        }
                    ],
                    "aggregate": {
                        "fieldType": "decimal"
                    },
                    "format": {
                        "unitFormat": "{0}",
                        "frequency": "daily",
                        "precision": 0
                    }
                }
            }
        };

        // Store the result as an array under the property name
        results[kpiPropertyName] = [resultObject];
    }

    return results;
}
